112	function canBindPort(port: number): Promise<boolean> {
113	    return new Promise((resolve) => {
114	        const probe = net.createServer();
115	
116	        const cleanup = () => {
117	            probe.removeAllListeners('error');
118	            probe.removeAllListeners('listening');
119	        };
120	
121	        probe.once('error', () => {
122	            cleanup();
123	            resolve(false);
124	        });
125	
126	        probe.once('listening', () => {
127	            cleanup();
128	            probe.close(() => resolve(true));
129	        });
130	
131	        try {
132	            probe.listen(port, HOST);
133	        } catch {
134	            cleanup();
135	            resolve(false);
136	        }
137	    });
138	}
