140	function listenOnPort(port: number): Promise<void> {
141	    return new Promise((resolve, reject) => {
142	        const handleError = (error: NodeJS.ErrnoException) => {
143	            server.off('listening', handleListening);
144	            reject(error);
145	        };
146	
147	        const handleListening = () => {
148	            server.off('error', handleError);
149	            resolve();
150	        };
151	
152	        server.once('error', handleError);
153	        server.once('listening', handleListening);
154	
155	        try {
156	            server.listen(port, HOST);
157	        } catch (error) {
158	            server.off('error', handleError);
159	            server.off('listening', handleListening);
160	            reject(error);
161	        }
162	    });
163	}
