530	async function gracefulShutdown(signal: string) {
531	    if (shuttingDown) return;
532	    shuttingDown = true;
533	
534	    bootLog(`⬡ SHUTDOWN_SIGNAL_RECEIVED :: ${signal}`);
535	    clearTrackedTimers();
536	    guard.stop();
537	
538	    try {
539	        await vaultWatcherController?.close();
540	        bootLog('⬡ VAULT_WATCHER_STOPPED');
541	    } catch (error: any) {
542	        bootLog(`⬡ VAULT_WATCHER_STOP_ERROR: ${error.message}`);
543	    }
544	
545	    wss?.clients.forEach((client) => {
546	        if (client.readyState === 1) {
547	            client.close(1001, 'Server shutting down');
548	        }
549	    });
550	
551	    const forcedExit = setTimeout(() => {
552	        bootLog('⬡ FORCED_EXIT :: Timed out while shutting down');
553	        process.exit(1);
554	    }, 5000);
555	
556	    try {
557	        if (wss) {
558	            await new Promise<void>((resolve) => wss!.close(() => resolve()));
559	        }
560	        await new Promise<void>((resolve) => server.close(() => resolve()));
561	    } finally {
562	        clearTimeout(forcedExit);
563	    }
564	
565	    try {
566	        db.close();
567	        bootLog('⬡ DATABASE_CLOSED');
568	    } catch (error: any) {
569	        bootLog(`⬡ DATABASE_CLOSE_ERROR: ${error.message}`);
570	    }
571	
572	    process.exit(0);
573	}
