583	async function startServer() {
584	    for (let index = 0; index < PORT_CANDIDATES.length; index += 1) {
585	        const port = PORT_CANDIDATES[index];
586	        currentPort = port;
587	        const nextPort = PORT_CANDIDATES[index + 1];
588	
589	        const bindable = await canBindPort(port);
590	        if (!bindable) {
591	            if (nextPort) {
592	                bootLog(`⬡ PORT_COLLISION :: ${port} unavailable. Trying ${nextPort}...`);
593	                continue;
594	            }
595	            break;
596	        }
597	
598	        try {
599	            await listenOnPort(port);
600	            wss = new WebSocketServer({ server });
601	            attachWebSocketServer(wss);
602	
603	            server.on('error', (error: any) => {
604	                bootLog(`⬡ SERVER_ERROR: ${error.message}`);
605	            });
606	
607	            bootLog(`⬡ NUDIMMUD_BACKEND_ONLINE :: ${HOST}:${currentPort}`);
608	            logEvent(db, 'SYSTEM', 'SERVER', `Backend server started on ${HOST}:${currentPort}`, 'INFO');
609	            return;
610	        } catch (error) {
611	            if (isRecoverableListenError(error) && nextPort) {
612	                bootLog(`⬡ PORT_COLLISION :: ${port} failed during bind (${error.code}). Trying ${nextPort}...`);
613	                continue;
614	            }
615	
616	            throw error;
617	        }
618	    }
619	
620	    throw new Error(`Port exhaustion. No ports available around ${DEFAULT_PORT}.`);
621	}
