566	    // Oracle SSE stream — pipes local LLM output as it arrives, no blocking wait
567	    router.get('/oracle/stream', async (req, res) => {
568	        const command = String(req.query.command || '').trim();
569	        const modelId = String(req.query.model || 'qwen-liberated:latest');
570	        if (!command) { res.status(400).json({ error: 'command required' }); return; }
571	
572	        res.setHeader('Content-Type', 'text/event-stream');
573	        res.setHeader('Cache-Control', 'no-cache');
574	        res.setHeader('Connection', 'keep-alive');
575	        res.setHeader('X-Accel-Buffering', 'no');
576	        res.flushHeaders();
577	
578	        const send = (event: string, data: unknown) => {
579	            res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
580	        };
581	
582	        send('start', { model: modelId, command });
583	
584	        try {
585	            const ollamaBase = process.env.OLLAMA_BASE_URL || 'http://localhost:11434';
586	            const fetch = (await import('node-fetch')).default;
587	            const upstream = await fetch(`${ollamaBase}/api/chat`, {
588	                method: 'POST',
589	                headers: { 'Content-Type': 'application/json' },
590	                body: JSON.stringify({
591	                    model: modelId,
592	                    messages: [{ role: 'user', content: command }],
593	                    stream: true
594	                }),
595	                signal: (req as any).signal
596	            });
597	
598	            if (!upstream.ok) throw new Error(`Ollama HTTP ${upstream.status}`);
599	            if (!upstream.body) throw new Error('No response body');
600	
601	            let full = '';
602	            for await (const chunk of upstream.body as any) {
603	                const text = chunk.toString();
604	                for (const line of text.split('\n').filter(Boolean)) {
605	                    try {
606	                        const parsed = JSON.parse(line);
607	                        const token = parsed?.message?.content || '';
608	                        if (token) {
609	                            full += token;
610	                            send('token', { token });
611	                        }
612	                        if (parsed?.done) {
613	                            send('done', { content: full, model: modelId });
614	                            res.end();
615	                            return;
616	                        }
617	                    } catch (_) {}
618	                }
619	            }
620	            send('done', { content: full, model: modelId });
621	        } catch (err: any) {
622	            send('error', { message: err.message || 'STREAM_FAILED' });
623	        }
624	        res.end();
625	    });
